'use client'

import * as React from 'react'

export const OWL_LOGO_DATA_URI =
  'data:image/png;base64,'

export interface OwlLogoProps extends React.ImgHTMLAttributes<HTMLImageElement> {
  size?: number
}

export function OwlLogo({
  size = 32,
  className = 'h-7 w-7 object-contain drop-shadow-xs select-none',
  alt = 'nungsue logo',
  ...props
}: OwlLogoProps) {
  return (
    <img
      src={OWL_LOGO_DATA_URI}
      alt={alt}
      width={size}
      height={size}
      className={className}
      {...props}
    />
  )
}

export default OwlLogo
